const brief = $input.item.json.body || $input.item.json;
const date = brief.date || new Date().toISOString().split('T')[0];

const marketLines = (brief.top_markets || []).map(m =>
  `${m.symbol}: $${(m.price||0).toLocaleString()} (${m.change_24h > 0 ? '+' : ''}${(m.change_24h||0).toFixed(2)}% 24h)`
).join('\n');

const trendingLines = (brief.trending_coins || []).map(c =>
  `${c.name} (${c.symbol})`
).join(', ');

const redditLines = (brief.reddit_top_posts || []).slice(0, 5).map(p =>
  `- [r/${p.subreddit}] ${p.title} (${p.score} upvotes)`
).join('\n');

const headlineLines = (brief.news_headlines || []).slice(0, 8).map(h =>
  `- ${h.title} (${h.source})`
).join('\n');

const mcap = brief.market_summary?.total_market_cap_usd
  ? '$' + (brief.market_summary.total_market_cap_usd / 1e12).toFixed(2) + 'T'
  : 'N/A';

const userPrompt = `Date: ${date}\n\nMARKET SUMMARY:\nTotal Market Cap: ${mcap}\nBTC Dominance: ${(brief.market_summary?.btc_dominance||0).toFixed(1)}%\n24h Market Change: ${(brief.market_summary?.market_cap_change_24h_pct||0).toFixed(2)}%\n\nTOP ASSETS (24h):\n${marketLines}\n\nTREND ING:\n${trendingLines}\n\nTOP REDDIT DISCUSSIONS:\n${redditLines}\n\nNEWS HEADLINES:\n${headlineLines}\n\nWrite the daily crypto market brief blog post for ${date}.`;

return [{ json: { date, user_prompt: userPrompt, sources: (brief.news_headlines || []).map(h => h.url).filter(Boolean) } }];

const claudeResp = $input.item.json;
const content = claudeResp.content?.[0]?.text || '';
const prev = $('Build Claude Prompt').item.json;
const date = prev.date;

const lines = content.split('\n').filter(l => l.trim());
const firstLine = lines[0] || '';
const title = firstLine.startsWith('#')
  ? firstLine.replace(/^#+\s*/, '').trim()
  : `Crypto Daily Brief \u2014 ${date}`;

const slug = 'crypto-daily-brief-' + date;

const summary = lines.find(l => !l.startsWith('#') && l.length > 50) || 'Daily crypto market analysis.';

const assetRegex = /\b(BTC|ETH|SOL|XRP|BNB|AVAX|DOGE|ADA|DOT|MATIC|LINK|UNI|AAVE|SNX|CRV|COMP|INJ|OP|ARB|SUI|APT|NEAR|FIL|LTC|BCH|SHIB|PEPE|FLOKI|BONK|WIF|POL)\b/g;
const assets = [...new Set(content.match(assetRegex) || ['BTC'])];

return [{
  json: {
    schema_version: 1,
    posts: [{
      slug,
      title,
      published_at: new Date().toISOString(),
      summary: summary.slice(0, 200),
      content,
      sources: prev.sources || [],
      assets,
      tags: ['daily-brief', 'market'],
      author: 'AlphaForgeAI'
    }]
  }
}];

